# No autotune - fixed XBLOCK=128, 80 registers/thread, 16 blocks on 132 SMs
@triton.jit
def kernel(in_ptr, out_ptr, xnumel, r0_numel, XBLOCK: tl.constexpr):
    ...

grid = (triton.cdiv(xnumel, 128),)  # = 16 blocks
kernel[grid](in_ptr, out_ptr, xnumel, r0_numel, XBLOCK=128)

@triton.autotune(
    configs=[
        triton.Config({'XBLOCK': 8},   num_warps=1, num_stages=1),
        triton.Config({'XBLOCK': 16},  num_warps=2, num_stages=1),
        triton.Config({'XBLOCK': 32},  num_warps=2, num_stages=1),
        triton.Config({'XBLOCK': 64},  num_warps=4, num_stages=1),
        triton.Config({'XBLOCK': 128}, num_warps=4, num_stages=1),
    ],
    key=['xnumel', 'r0_numel'],
)
@triton.jit
def kernel(in_ptr, out_ptr, xnumel, r0_numel, XBLOCK: tl.constexpr):
    ...

# BUG: static grid ignores autotuned XBLOCK
grid = (triton.cdiv(xnumel, 128),)  # always 16 blocks
kernel[grid](in_ptr, out_ptr, xnumel, r0_numel)

# @triton.autotune present but call site uses static grid — autotune XBLOCK selection has no effect on grid
