    configs=[triton.Config({'XBLOCK': 1}), ..., triton.Config({'XBLOCK': 128})],
    key=['xnumel', 'r0_numel'],
)
@triton.jit
def kernel(..., XBLOCK: tl.constexpr): ...

grid = (triton.cdiv(xnumel, 128),)  # WRONG: always 16 blocks regardless of autotune choice
kernel[grid](arg_0, arg_1, xnumel, r0_numel)

fast_pseudocode:
# Grid lambda scales with autotune-selected XBLOCK
@triton.autotune(
    configs=[triton.Config({'XBLOCK': 1}), ..., triton.Config({'XBLOCK': 128})],
    key=['xnumel', 'r0_numel'],
)
@triton.jit
def kernel(..., XBLOCK: tl.constexpr): ...

grid = lambda meta: (triton.cdiv(xnumel, meta['XBLOCK']),)  # CORRECT: scales with chosen XBLOCK
kernel[grid](arg_0, arg_1, xnumel, r0_numel)  # do NOT pass XBLOCK= kwarg; autotune injects it
